//! Generates `src/proto/resolved_ast.zig` from `proto/googlesql.fdset`.
//!
//! Reads a protoc FileDescriptorSet and emits plain Zig structs plus per-message
//! decode functions over the hand-written wire reader in `src/proto/wire.zig`.
//!
//! Run: `zig build gen-proto`
//!
//! The .fdset is committed, so this only needs rerunning when the googlesql
//! submodule moves. resolved_ast.proto is generated by Bazel into the external
//! repo tree, whose canonical directory name is version-dependent (googlesql~ on
//! Bazel 7.6, googlesql+ on newer) — discover it rather than hardcoding it:
//!
//!     bazel build -c opt @googlesql//googlesql/resolved_ast:resolved_ast_proto
//!     GS=$(dirname "$(bazel cquery --output=files \
//!         @googlesql//googlesql/resolved_ast:resolved_ast_proto | head -1)")
//!     protoc -I third_party/googlesql -I "$GS/../../.." --include_imports \
//!         --descriptor_set_out=proto/googlesql.fdset "$GS/resolved_ast.proto"
//!
//! Representation choices (mirrored by the extractor):
//! - optional scalar field  -> ?T
//! - optional message field -> ?*T (arena-allocated; breaks recursion cycles)
//! - repeated field         -> []T / []*T slice (arena-allocated)
//! - oneof                  -> optional tagged union
//! - enum                   -> non-exhaustive enum(i32) so unknown future values
//!                             decode without error
//! - string/bytes           -> []const u8 borrowing from the input buffer (the
//!                             buffer must outlive the decoded tree; both are
//!                             arena-owned in practice)
//! - unknown fields are skipped; proto2 `required` is not enforced.
//!
//! **This generator is self-hosting.** `--include_imports` pulled
//! `descriptor.proto` into the .fdset, so the file this writes also contains the
//! `FileDescriptorSet` decoders used to read the .fdset in the first place — the
//! `pb` module is the previous run's output. If a bad .fdset ever produces
//! output that does not compile, the generator can no longer be built to fix it;
//! recover with `git checkout src/proto/resolved_ast.zig`.
//!
//! Ported from the retired `tools/gen_proto.py`, which needed a pip-installed
//! `protobuf` (and the `tools/venv` that came with it). Output is not
//! byte-identical to that script's — `zig build gen-proto` runs `zig fmt` over
//! the result, so this emits structurally correct Zig and lets the formatter
//! decide layout.
const std = @import("std");
const pb = @import("pb");

const Ty = pb.FieldDescriptorProto_Type;

const Error = error{
    /// A descriptor was missing a field protoc always sets.
    MalformedDescriptor,
    /// proto2 `group` fields have no representation here.
    UnsupportedGroup,
    UnknownType,
} || std.mem.Allocator.Error;

const zig_keywords = std.StaticStringMap(void).initComptime(.{
    .{"align"},          .{"allowzero"}, .{"and"},      .{"anyframe"},
    .{"anytype"},        .{"asm"},       .{"async"},    .{"await"},
    .{"break"},          .{"callconv"},  .{"catch"},    .{"comptime"},
    .{"const"},          .{"continue"},  .{"defer"},    .{"else"},
    .{"enum"},           .{"errdefer"},  .{"error"},    .{"export"},
    .{"extern"},         .{"fn"},        .{"for"},      .{"if"},
    .{"inline"},         .{"noalias"},   .{"noinline"}, .{"nosuspend"},
    .{"opaque"},         .{"or"},        .{"orelse"},   .{"packed"},
    .{"pub"},            .{"resume"},    .{"return"},   .{"linksection"},
    .{"struct"},         .{"suspend"},   .{"switch"},   .{"test"},
    .{"threadlocal"},    .{"try"},       .{"union"},    .{"unreachable"},
    .{"usingnamespace"}, .{"var"},       .{"volatile"}, .{"while"},
    // primitive-ish names that shadow builtins
    .{"type"},           .{"bool"},      .{"true"},     .{"false"},
    .{"null"},           .{"undefined"},
});

/// Field/decl identifier, escaped if it collides with a Zig keyword.
fn zid(a: std.mem.Allocator, name: []const u8) Error![]const u8 {
    if (zig_keywords.has(name) or (name.len > 0 and std.ascii.isDigit(name[0]))) {
        return std.fmt.allocPrint(a, "@\"{s}\"", .{name});
    }
    return name;
}

/// Python's `str.capitalize()`: upper-cases the first character and lower-cases
/// every other one. `foo_BAR` -> `FooBar`, not `FooBAR`.
fn capitalize(a: std.mem.Allocator, word: []const u8) Error![]u8 {
    const buf = try a.alloc(u8, word.len);
    for (word, 0..) |c, i| {
        buf[i] = if (i == 0) std.ascii.toUpper(c) else std.ascii.toLower(c);
    }
    return buf;
}

/// `"".join(p.capitalize() for p in name.split("_")) + "Union"`.
fn oneofUnionName(a: std.mem.Allocator, name: []const u8) Error![]const u8 {
    var buf: std.ArrayList(u8) = .empty;
    var it = std.mem.splitScalar(u8, name, '_');
    while (it.next()) |part| try buf.appendSlice(a, try capitalize(a, part));
    try buf.appendSlice(a, "Union");
    return buf.items;
}

/// The segment after the last `.` of a fully-qualified proto name.
fn lastSegment(fq: []const u8) []const u8 {
    if (std.mem.lastIndexOfScalar(u8, fq, '.')) |i| return fq[i + 1 ..];
    return fq;
}

fn scalarZig(t: Ty) Error![]const u8 {
    return switch (t) {
        .TYPE_DOUBLE => "f64",
        .TYPE_FLOAT => "f32",
        .TYPE_INT64 => "i64",
        .TYPE_UINT64 => "u64",
        .TYPE_INT32 => "i32",
        .TYPE_FIXED64 => "u64",
        .TYPE_FIXED32 => "u32",
        .TYPE_BOOL => "bool",
        .TYPE_STRING => "[]const u8",
        .TYPE_BYTES => "[]const u8",
        .TYPE_UINT32 => "u32",
        .TYPE_SFIXED32 => "i32",
        .TYPE_SFIXED64 => "i64",
        .TYPE_SINT32 => "i32",
        .TYPE_SINT64 => "i64",
        else => error.UnknownType,
    };
}

/// wire.Reader expression producing the raw value for each scalar type, reading
/// from `recv` (`r` for a top-level field, `sub` inside a packed run).
fn scalarRead(a: std.mem.Allocator, t: Ty, recv: []const u8) Error![]const u8 {
    return switch (t) {
        .TYPE_DOUBLE => std.fmt.allocPrint(a, "try {s}.readDouble()", .{recv}),
        .TYPE_FLOAT => std.fmt.allocPrint(a, "try {s}.readFloat()", .{recv}),
        .TYPE_INT64 => std.fmt.allocPrint(a, "try {s}.readInt64()", .{recv}),
        .TYPE_UINT64 => std.fmt.allocPrint(a, "try {s}.readVarint()", .{recv}),
        .TYPE_INT32 => std.fmt.allocPrint(a, "try {s}.readInt32()", .{recv}),
        .TYPE_FIXED64 => std.fmt.allocPrint(a, "try {s}.readFixed64()", .{recv}),
        .TYPE_FIXED32 => std.fmt.allocPrint(a, "try {s}.readFixed32()", .{recv}),
        .TYPE_BOOL => std.fmt.allocPrint(a, "(try {s}.readVarint()) != 0", .{recv}),
        .TYPE_STRING => std.fmt.allocPrint(a, "try {s}.readBytes()", .{recv}),
        .TYPE_BYTES => std.fmt.allocPrint(a, "try {s}.readBytes()", .{recv}),
        .TYPE_UINT32 => std.fmt.allocPrint(a, "@truncate(try {s}.readVarint())", .{recv}),
        .TYPE_SFIXED32 => std.fmt.allocPrint(a, "@bitCast(try {s}.readFixed32())", .{recv}),
        .TYPE_SFIXED64 => std.fmt.allocPrint(a, "@bitCast(try {s}.readFixed64())", .{recv}),
        .TYPE_SINT32 => std.fmt.allocPrint(a, "try {s}.readSint32()", .{recv}),
        .TYPE_SINT64 => std.fmt.allocPrint(a, "try {s}.readSint64()", .{recv}),
        else => error.UnknownType,
    };
}

/// Scalars that may appear packed. Mirrors the Python's
/// `set(SCALAR_READ) - {STRING, BYTES}` — note enums are absent from that table,
/// so a repeated enum is only ever decoded unpacked. Preserved deliberately.
fn isPackable(t: Ty) bool {
    return switch (t) {
        .TYPE_DOUBLE,
        .TYPE_FLOAT,
        .TYPE_INT64,
        .TYPE_UINT64,
        .TYPE_INT32,
        .TYPE_FIXED64,
        .TYPE_FIXED32,
        .TYPE_BOOL,
        .TYPE_UINT32,
        .TYPE_SFIXED32,
        .TYPE_SFIXED64,
        .TYPE_SINT32,
        .TYPE_SINT64,
        => true,
        else => false,
    };
}

const Msg = struct {
    fq: []const u8,
    desc: *pb.DescriptorProto,
    /// Nested-name prefix, e.g. "TypeProto_".
    parent_prefix: []const u8,
};

const Enm = struct {
    fq: []const u8,
    desc: *pb.EnumDescriptorProto,
    parent_prefix: []const u8,
};

const Gen = struct {
    a: std.mem.Allocator,
    msgs: std.StringHashMapUnmanaged(Msg) = .empty,
    enums: std.StringHashMapUnmanaged(Enm) = .empty,
    msg_keys: std.ArrayList([]const u8) = .empty,
    enum_keys: std.ArrayList([]const u8) = .empty,
    /// Fully-qualified proto name -> flat Zig type name.
    names: std.StringHashMapUnmanaged([]const u8) = .empty,
    out: std.ArrayList(u8) = .empty,

    fn line(g: *Gen, comptime fmt: []const u8, args: anytype) Error!void {
        try g.out.print(g.a, fmt ++ "\n", args);
    }

    // ---- collect ----

    fn collect(g: *Gen, fds: *pb.FileDescriptorSet) Error!void {
        for (fds.file) |f| {
            const pkg: []const u8 = if (f.package) |p|
                (if (p.len > 0) try std.fmt.allocPrint(g.a, ".{s}", .{p}) else "")
            else
                "";
            for (f.message_type) |d| try g.walkMsg(pkg, "", d);
            for (f.enum_type) |e| {
                const name = e.name orelse return error.MalformedDescriptor;
                try g.putEnum(.{
                    .fq = try std.fmt.allocPrint(g.a, "{s}.{s}", .{ pkg, name }),
                    .desc = e,
                    .parent_prefix = "",
                });
            }
        }
    }

    fn walkMsg(g: *Gen, pkg_fq: []const u8, prefix: []const u8, d: *pb.DescriptorProto) Error!void {
        const name = d.name orelse return error.MalformedDescriptor;
        const fq = try std.fmt.allocPrint(g.a, "{s}.{s}", .{ pkg_fq, name });
        try g.putMsg(.{ .fq = fq, .desc = d, .parent_prefix = prefix });

        // Map fields appear as repeated map-entry messages; the entry struct is
        // still generated so decode has a type to target.
        const nested_prefix = try std.fmt.allocPrint(g.a, "{s}{s}_", .{ prefix, name });
        for (d.nested_type) |nested| try g.walkMsg(fq, nested_prefix, nested);
        for (d.enum_type) |e| {
            const ename = e.name orelse return error.MalformedDescriptor;
            try g.putEnum(.{
                .fq = try std.fmt.allocPrint(g.a, "{s}.{s}", .{ fq, ename }),
                .desc = e,
                .parent_prefix = nested_prefix,
            });
        }
    }

    fn putMsg(g: *Gen, m: Msg) Error!void {
        const gop = try g.msgs.getOrPut(g.a, m.fq);
        if (!gop.found_existing) try g.msg_keys.append(g.a, m.fq);
        gop.value_ptr.* = m;
    }

    fn putEnum(g: *Gen, e: Enm) Error!void {
        const gop = try g.enums.getOrPut(g.a, e.fq);
        if (!gop.found_existing) try g.enum_keys.append(g.a, e.fq);
        gop.value_ptr.* = e;
    }

    // ---- naming ----

    /// Maps fully-qualified proto names to flat Zig type names, qualifying with
    /// the package wherever the flat name would collide.
    fn resolveNames(g: *Gen) Error!void {
        var base_count: std.StringHashMapUnmanaged(u32) = .empty;
        for (g.msg_keys.items) |fq| {
            const m = g.msgs.get(fq).?;
            const gop = try base_count.getOrPut(g.a, try g.baseName(m.parent_prefix, fq));
            gop.value_ptr.* = if (gop.found_existing) gop.value_ptr.* + 1 else 1;
        }
        for (g.enum_keys.items) |fq| {
            const e = g.enums.get(fq).?;
            const gop = try base_count.getOrPut(g.a, try g.baseName(e.parent_prefix, fq));
            gop.value_ptr.* = if (gop.found_existing) gop.value_ptr.* + 1 else 1;
        }

        for (g.msg_keys.items) |fq| {
            const m = g.msgs.get(fq).?;
            try g.names.put(g.a, fq, try g.zigName(m.parent_prefix, fq, base_count));
        }
        for (g.enum_keys.items) |fq| {
            const e = g.enums.get(fq).?;
            try g.names.put(g.a, fq, try g.zigName(e.parent_prefix, fq, base_count));
        }
    }

    fn baseName(g: *Gen, parent_prefix: []const u8, fq: []const u8) Error![]const u8 {
        return std.fmt.allocPrint(g.a, "{s}{s}", .{ parent_prefix, lastSegment(fq) });
    }

    fn zigName(
        g: *Gen,
        parent_prefix: []const u8,
        fq: []const u8,
        base_count: std.StringHashMapUnmanaged(u32),
    ) Error![]const u8 {
        const base = try g.baseName(parent_prefix, fq);
        if ((base_count.get(base) orelse 0) <= 1) return base;

        // Qualify with the package (e.g. google.protobuf collisions).
        const without_dot = if (fq.len > 0 and fq[0] == '.') fq[1..] else fq;
        const pkg = if (std.mem.lastIndexOfScalar(u8, without_dot, '.')) |i|
            without_dot[0..i]
        else
            without_dot;
        const flat = try g.a.dupe(u8, pkg);
        std.mem.replaceScalar(u8, flat, '.', '_');
        return std.fmt.allocPrint(g.a, "{s}_{s}", .{ flat, base });
    }

    fn typeName(g: *Gen, f: *pb.FieldDescriptorProto) Error![]const u8 {
        const tn = f.type_name orelse return error.MalformedDescriptor;
        return g.names.get(tn) orelse error.MalformedDescriptor;
    }

    fn fieldZigType(g: *Gen, f: *pb.FieldDescriptorProto) Error![]const u8 {
        const t = f.type orelse return error.MalformedDescriptor;
        return switch (t) {
            .TYPE_MESSAGE, .TYPE_ENUM => try g.typeName(f),
            .TYPE_GROUP => error.UnsupportedGroup,
            else => scalarZig(t),
        };
    }

    fn readExpr(g: *Gen, f: *pb.FieldDescriptorProto) Error![]const u8 {
        const t = f.type orelse return error.MalformedDescriptor;
        return switch (t) {
            .TYPE_MESSAGE => std.fmt.allocPrint(
                g.a,
                "try {s}.decodeReader(a, &sub)",
                .{try g.typeName(f)},
            ),
            .TYPE_ENUM => std.fmt.allocPrint(
                g.a,
                "@as({s}, @enumFromInt(try r.readInt32()))",
                .{try g.typeName(f)},
            ),
            else => scalarRead(g.a, t, "r"),
        };
    }

    // ---- emit ----

    fn genEnum(g: *Gen, e: Enm) Error!void {
        try g.line("pub const {s} = enum(i32) {{", .{g.names.get(e.fq).?});
        var seen: std.AutoHashMapUnmanaged(i32, void) = .empty;
        for (e.desc.value) |v| {
            const number = v.number orelse return error.MalformedDescriptor;
            const name = v.name orelse return error.MalformedDescriptor;
            // allow_alias duplicates: keep the first spelling of each number.
            if ((try seen.getOrPut(g.a, number)).found_existing) continue;
            try g.line("    {s} = {d},", .{ try zid(g.a, name), number });
        }
        try g.line("    _,", .{});
        try g.line("}};", .{});
        try g.line("", .{});
    }

    fn genMessage(g: *Gen, m: Msg) Error!void {
        const zname = g.names.get(m.fq).?;
        const d = m.desc;

        // Partition fields into oneof buckets and plain fields.
        const oneofs = try g.a.alloc(std.ArrayList(*pb.FieldDescriptorProto), d.oneof_decl.len);
        for (oneofs) |*o| o.* = .empty;
        var plain: std.ArrayList(*pb.FieldDescriptorProto) = .empty;
        for (d.field) |f| {
            if (f.oneof_index) |oi| {
                try oneofs[@intCast(oi)].append(g.a, f);
            } else {
                try plain.append(g.a, f);
            }
        }

        try g.line("pub const {s} = struct {{", .{zname});

        // Oneof unions first.
        for (d.oneof_decl, 0..) |decl, oi| {
            if (oneofs[oi].items.len == 0) continue;
            const uname = try oneofUnionName(g.a, decl.name orelse return error.MalformedDescriptor);
            try g.line("    pub const {s} = union(enum) {{", .{uname});
            for (oneofs[oi].items) |f| {
                const t = try g.fieldZigType(f);
                const ptr = f.type.? == .TYPE_MESSAGE;
                try g.line("        {s}: {s}{s},", .{
                    try zid(g.a, f.name orelse return error.MalformedDescriptor),
                    if (ptr) "*" else "",
                    t,
                });
            }
            try g.line("    }};", .{});
        }

        // Fields.
        for (plain.items) |f| {
            const t = try g.fieldZigType(f);
            const fname = try zid(g.a, f.name orelse return error.MalformedDescriptor);
            const is_msg = f.type.? == .TYPE_MESSAGE;
            if (f.label == .LABEL_REPEATED) {
                try g.line("    {s}: []{s}{s} = &.{{}},", .{ fname, if (is_msg) "*" else "", t });
            } else if (is_msg) {
                try g.line("    {s}: ?*{s} = null,", .{ fname, t });
            } else {
                try g.line("    {s}: ?{s} = null,", .{ fname, t });
            }
        }
        for (d.oneof_decl, 0..) |decl, oi| {
            if (oneofs[oi].items.len == 0) continue;
            const dname = decl.name orelse return error.MalformedDescriptor;
            try g.line("    {s}: ?{s} = null,", .{
                try zid(g.a, dname),
                try oneofUnionName(g.a, dname),
            });
        }

        // decode() entry point and decodeReader().
        try g.line("", .{});
        try g.line(
            "    pub fn decode(a: std.mem.Allocator, buf: []const u8) wire.DecodeError!*{s} {{",
            .{zname},
        );
        try g.line("        var r = wire.Reader.init(buf);", .{});
        try g.line("        return decodeReader(a, &r);", .{});
        try g.line("    }}", .{});
        try g.line("", .{});
        try g.line(
            "    pub fn decodeReader(a: std.mem.Allocator, r: *wire.Reader) wire.DecodeError!*{s} {{",
            .{zname},
        );
        try g.line("        const msg = try a.create({s});", .{zname});
        try g.line("        msg.* = .{{}};", .{});

        for (plain.items) |f| {
            if (f.label != .LABEL_REPEATED) continue;
            const t = try g.fieldZigType(f);
            const is_msg = f.type.? == .TYPE_MESSAGE;
            try g.line("        var list_{s}: std.ArrayList({s}{s}) = .empty;", .{
                f.name.?,
                if (is_msg) "*" else "",
                t,
            });
        }

        try g.line("        while (try r.next()) |tag| {{", .{});
        try g.line("            switch (tag.field) {{", .{});
        for (d.field) |f| try g.genFieldCase(d, f);
        try g.line("                else => try r.skip(tag.wire),", .{});
        try g.line("            }}", .{});
        try g.line("        }}", .{});

        for (plain.items) |f| {
            if (f.label != .LABEL_REPEATED) continue;
            try g.line("        msg.{s} = try list_{s}.toOwnedSlice(a);", .{
                try zid(g.a, f.name.?),
                f.name.?,
            });
        }
        try g.line("        return msg;", .{});
        try g.line("    }}", .{});
        try g.line("}};", .{});
        try g.line("", .{});
    }

    fn genFieldCase(g: *Gen, d: *pb.DescriptorProto, f: *pb.FieldDescriptorProto) Error!void {
        const number = f.number orelse return error.MalformedDescriptor;
        const name = f.name orelse return error.MalformedDescriptor;
        const t = f.type orelse return error.MalformedDescriptor;
        const is_oneof = f.oneof_index != null;

        try g.line("                {d} => {{", .{number});
        if (f.label == .LABEL_REPEATED and !is_oneof) {
            if (isPackable(t)) {
                // Accept both packed and unpacked encodings.
                try g.line("                    if (tag.wire == .len) {{", .{});
                try g.line("                        var sub = try r.subReader();", .{});
                try g.line("                        while (!sub.atEnd()) {{", .{});
                try g.line("                            try list_{s}.append(a, {s});", .{
                    name,
                    try scalarRead(g.a, t, "sub"),
                });
                try g.line("                        }}", .{});
                try g.line("                    }} else {{", .{});
                try g.line("                        try list_{s}.append(a, {s});", .{
                    name,
                    try scalarRead(g.a, t, "r"),
                });
                try g.line("                    }}", .{});
            } else if (t == .TYPE_MESSAGE) {
                try g.line("                    var sub = try r.subReader();", .{});
                try g.line("                    try list_{s}.append(a, {s});", .{
                    name,
                    try g.readExpr(f),
                });
            } else { // string/bytes, and enums (never packed here)
                try g.line("                    try list_{s}.append(a, {s});", .{
                    name,
                    try g.readExpr(f),
                });
            }
        } else {
            if (t == .TYPE_MESSAGE) {
                try g.line("                    var sub = try r.subReader();", .{});
            }
            const val = try g.readExpr(f);
            if (is_oneof) {
                const decl = d.oneof_decl[@intCast(f.oneof_index.?)];
                try g.line("                    msg.{s} = .{{ .{s} = {s} }};", .{
                    try zid(g.a, decl.name orelse return error.MalformedDescriptor),
                    try zid(g.a, name),
                    val,
                });
            } else {
                try g.line("                    msg.{s} = {s};", .{ try zid(g.a, name), val });
            }
        }
        try g.line("                }},", .{});
    }
};

fn lessThan(_: void, a: []const u8, b: []const u8) bool {
    return std.mem.order(u8, a, b) == .lt;
}

pub fn main(init: std.process.Init) !void {
    var stderr_buf: [4096]u8 = undefined;
    var stderr_writer = std.Io.File.stderr().writerStreaming(init.io, &stderr_buf);
    const err_out = &stderr_writer.interface;

    var arena_state = std.heap.ArenaAllocator.init(std.heap.smp_allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    var args = std.process.Args.Iterator.init(init.minimal.args);
    _ = args.next();
    const fdset_path = args.next() orelse {
        try err_out.writeAll("usage: gen-proto <googlesql.fdset> <out.zig>\n");
        try err_out.flush();
        std.process.exit(2);
    };
    const out_path = args.next() orelse {
        try err_out.writeAll("usage: gen-proto <googlesql.fdset> <out.zig>\n");
        try err_out.flush();
        std.process.exit(2);
    };

    const bytes = try std.Io.Dir.cwd().readFileAlloc(init.io, fdset_path, arena, .limited(1 << 26));
    const fds = try pb.FileDescriptorSet.decode(arena, bytes);

    var g: Gen = .{ .a = arena };
    try g.collect(fds);
    try g.resolveNames();

    std.mem.sort([]const u8, g.msg_keys.items, {}, lessThan);
    std.mem.sort([]const u8, g.enum_keys.items, {}, lessThan);

    try g.line("//! GENERATED by tools/gen_proto.zig from proto/googlesql.fdset — do not edit.", .{});
    try g.line("//! Plain-struct decoders for the googlesql resolved AST protos.", .{});
    try g.line("", .{});
    try g.line("const std = @import(\"std\");", .{});
    try g.line("pub const wire = @import(\"wire.zig\");", .{});
    try g.line("", .{});
    for (g.enum_keys.items) |fq| try g.genEnum(g.enums.get(fq).?);
    for (g.msg_keys.items) |fq| try g.genMessage(g.msgs.get(fq).?);

    try std.Io.Dir.cwd().writeFile(init.io, .{ .sub_path = out_path, .data = g.out.items });
    try err_out.print("wrote {s}: {d} messages, {d} enums\n", .{
        out_path,
        g.msg_keys.items.len,
        g.enum_keys.items.len,
    });
    try err_out.flush();
}
